 import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, SRGBColorSpace, LinearFilter } = ctx.THREE;

  const region = config.atlasRegion ?? { sourceRect: [0, 0, 512, 320] };
  const [rx, ry, rw, rh] = Array.isArray(region.sourceRect)
    ? region.sourceRect
    : [0, 0, 512, 320];

  const aspect = rw / rh;
  const cardHeight = 0.8;
  const cardWidth = cardHeight * aspect;

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    toneMapped: false,
    transparent: false,
  });

  const mesh = new Mesh(geometry, material);
  mesh.name = config.id ?? 'feature-card-1';
  mesh.userData.handlers = {};
  mesh.userData.timelines = [];

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.minFilter = LinearFilter;
      tex.magFilter = LinearFilter;
      tex.generateMipmaps = false;
      tex.anisotropy = 4;
      material.map = tex;
      material.needsUpdate = true;
      loadedTexture = tex;
    }).catch(() => {});
  }

  mesh.userData.cleanup = () => {
    mesh.userData.timelines.forEach((tl) => tl.kill());
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    material.dispose();
    geometry.dispose();
  };

  return mesh;
}
